'use strict';

const KEY = 'wordscene-v2';
const firstStory = STORIES[0]?.id || '';
const fresh = () => ({version:2, goal:10, words:{}, favorites:[], completed:[], custom:[], activity:{}, notes:{}, lastStory:firstStory, preferences:{english:false}});
const today = () => {const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const afterDays = n => {const d=new Date();d.setDate(d.getDate()+n);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const esc = s => String(s ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const shuffle = a => {const b=[...a];for(let i=b.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[b[i],b[j]]=[b[j],b[i]];}return b;};

function cleanState(raw){
  const s=fresh(); if(!raw||typeof raw!=='object') return s;
  if([10,20,30,50].includes(raw.goal)) s.goal=raw.goal;
  const builtin=new Set(BUILTIN_WORDS.map(w=>w.id));
  s.custom=Array.isArray(raw.custom)?raw.custom.slice(0,1500).filter(w=>w&&/^[a-z][a-z '-]{0,49}$/i.test(w.word||'')&&typeof w.meaning==='string').map(w=>({id:w.word.toLowerCase(),word:w.word.toLowerCase(),meaning:w.meaning.slice(0,150),pos:w.pos||'自定义',phrase:w.phrase||'',example:w.example||'',source:'我的生词',storyId:null})):[];
  s.custom=[...new Map(s.custom.filter(w=>!builtin.has(w.id)).map(w=>[w.id,w])).values()];
  const ids=new Set([...BUILTIN_WORDS,...s.custom].map(w=>w.id));
  if(raw.words&&typeof raw.words==='object') for(const [id,p] of Object.entries(raw.words)) if(ids.has(id)&&p&&Number.isInteger(p.stage)&&p.stage>=0&&p.stage<=4&&typeof p.due==='string') s.words[id]={stage:p.stage,due:p.due,last:p.last||'',attempts:Number(p.attempts)||0};
  if(Array.isArray(raw.favorites)) s.favorites=[...new Set(raw.favorites.filter(id=>ids.has(id)))];
  if(Array.isArray(raw.completed)) s.completed=raw.completed.filter(isKnownWordsceneStory);
  if(isKnownWordsceneStory(raw.lastStory)) s.lastStory=raw.lastStory;
  if(raw.activity&&typeof raw.activity==='object') for(const [date,list] of Object.entries(raw.activity)) if(/^\d{4}-\d{2}-\d{2}$/.test(date)&&Array.isArray(list)) s.activity[date]=[...new Set(list.filter(id=>ids.has(id)))];
  if(raw.notes&&typeof raw.notes==='object') s.notes=Object.fromEntries(Object.entries(raw.notes).filter(([id,n])=>ids.has(id)&&typeof n==='string').map(([id,n])=>[id,n.slice(0,500)]));
  s.preferences={english:Boolean(raw.preferences?.english)};
  return s;
}

let storageAvailable=true,state;
try{state=cleanState(JSON.parse(localStorage.getItem(KEY)||localStorage.getItem('wordscene-v1')));}catch{state=fresh();storageAvailable=false;}
const allWords=()=>[...BUILTIN_WORDS,...state.custom];
const getWord=id=>BUILTIN_INDEX.get(id)||state.custom.find(w=>w.id===id);
let getStory=id=>STORY_INDEX.get(id);
let category='全部',search='',sortUnread=false,notebookFilter='all',notebookSearch='',notebookLimit=40,quiz=null,selectedWord=null,toastTimer,activeSpeech=null;
const main=document.getElementById('main'),wordDialog=document.getElementById('word-dialog'),utilityDialog=document.getElementById('utility-dialog');

function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageAvailable=true;}catch{storageAvailable=false;toast('当前浏览器无法保存，请导出备份。');}updateNav();}
function toast(message){clearTimeout(toastTimer);const el=document.getElementById('toast');if(!el)return;el.textContent=message;el.classList.add('show');toastTimer=setTimeout(()=>el.classList.remove('show'),3200);}
function dueWords(){return allWords().filter(w=>state.words[w.id]?.due<=today());}
function record(id,correct){const old=state.words[id],stage=correct?Math.min((old?.stage||0)+1,4):0;state.words[id]={stage,due:afterDays([0,1,3,7,14][stage]),last:today(),attempts:(old?.attempts||0)+1};state.activity[today()]=[...new Set([...(state.activity[today()]||[]),id])];save();}
function streak(){let n=0,d=new Date();if(!state.activity[today()]?.length)d.setDate(d.getDate()-1);for(let i=0;i<10000;i++){const k=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;if(!state.activity[k]?.length)break;n++;d.setDate(d.getDate()-1);}return n;}
function updateNav(){const badge=document.getElementById('nav-due');if(badge)badge.textContent=dueWords().length;const route=location.hash.split('/')[0].slice(1)||'library';document.querySelectorAll('[data-nav]').forEach(el=>el.classList.toggle('active',el.dataset.nav===(['story','quiz'].includes(route)?'library':route)));}
function statusFor(w){const p=state.words[w.id];return !p?['new','未学习']:p.due<=today()?['due','待复习']:p.stage>=4?['done','已巩固']:['learned','已记住'];}
function stats(){const learned=Object.values(state.words).filter(p=>p.stage>0).length,done=state.activity[today()]?.length||0;return `<div class="stats-strip"><div class="stat"><span class="stat-icon">▤</span><div><strong>${STORIES.length}<small>篇原创故事</small></strong><p>修仙志与悬疑案双主线</p></div></div><div class="stat"><span class="stat-icon">✓</span><div><strong>${learned}<small>/ ${allWords().length} 词已掌握</small></strong><p>重点词 + 六级扩展词库</p></div></div><div class="stat"><span class="stat-icon">↻</span><div><strong>${dueWords().length}<small>词待复习</small></strong><p>今天再遇见一次</p></div></div><div class="stat daily-stat"><div style="width:100%"><strong>${done}<small>/ ${state.goal} 今日目标 · 连续 ${streak()} 天</small></strong><div class="tiny-progress"><span style="width:${Math.min(100,done/state.goal*100)}%"></span></div><p>${done>=state.goal?'今日任务已完成。':'中文先读，记住画面，再回忆英文。'}</p></div></div></div>`;}

function storyCard(s){const known=s.words.filter(w=>state.words[w.id]?.stage>0).length;return `<a class="story-card" href="#story/${s.id}"><div class="cover" style="--cover:${s.color};--cover-ink:#52635f"><div><div class="cover-type">${esc(s.category)} · ${esc(s.tag)}</div><div class="cover-title">${esc(s.en)}</div></div><div class="cover-symbol">${s.symbol}</div><span class="cover-no">CHAPTER ${String(s.number).padStart(2,'0')}</span></div><div class="card-body"><div class="card-tags"><span class="tag">${esc(s.category)}</span><span>${state.completed.includes(s.id)?'✓ 已读':'约 4 分钟'} · ${s.words.length} 词</span></div><h3>${esc(s.title)}</h3><p>${esc(s.cn[0])}</p><div class="card-bottom"><span>${known?`${known} / ${s.words.length} 词已记住`:esc(s.mood)}</span><span>${state.completed.includes(s.id)?'再读一次':'打开故事'} ↗</span></div></div></a>`;}
function filteredStories(){let list=STORIES.filter(s=>(category==='全部'||s.category===category)&&(!search||[s.title,s.en,s.category,s.tag,...s.words.map(w=>`${w.word} ${w.meaning}`)].join(' ').toLowerCase().includes(search.toLowerCase())));if(sortUnread)list.sort((a,b)=>Number(state.completed.includes(a.id))-Number(state.completed.includes(b.id)));return list;}
function renderCards(){const list=filteredStories(),count=document.getElementById('story-count'),grid=document.getElementById('story-grid');if(!count||!grid)return;count.textContent=`${list.length} 篇故事 · ${list.reduce((n,s)=>n+s.words.length,0)} 个语境词`;grid.innerHTML=list.length?list.map(storyCard).join(''):`<div class="empty-state" style="grid-column:1/-1"><h2>没有找到匹配故事</h2><p>换一个关键词，或者看看全部章节。</p><button class="button secondary" data-action="clear-search">查看全部</button></div>`;}
function library(){main.innerHTML=`<section class="hero"><div><div class="eyebrow">WORDSCENE · CET-6 READING</div><h1>先读中文语境，<br>再把英文<em>想起来。</em></h1><p>不做爽文式的单词堆砌。<br>在修仙志的因果与悬疑案的线索里，先看懂人物发生了什么，再主动回忆六级词汇。</p><div class="hero-actions"><a class="button" href="#story/${state.lastStory}">${state.completed.length?'继续上次阅读':'进入第一章'} <span>↗</span></a><a class="text-link" href="#review">${dueWords().length?`复习 ${dueWords().length} 个到期词`:'开启今日复习'} →</a></div></div><div class="hero-art" aria-hidden="true"><div class="orb"></div><div class="spark">✦</div><div class="book one"><small>CULTIVATION FILE</small><strong>云门试炼<br>第三声钟</strong><i>先读因果，再记词义</i></div><div class="book two"><small>MYSTERY CASE</small><strong>第七码头<br>匿名线报</strong><i>每个线索，都有英文</i></div><div class="book three"><small>CET-6 WORD BANK</small><strong>${allWords().length}<br>词可复习</strong><i>context before recall</i></div><span class="art-label">中文语境优先 · 主动回忆巩固</span></div></section>${stats()}<section aria-labelledby="shelf-heading"><div class="section-title"><h2 id="shelf-heading">今日书架 <span>THE STORY ARCHIVE</span></h2><p>先读中文 · 展开英文 · 点击词汇 · 读完测验</p></div><div class="library-tools"><div class="filters">${['全部','修仙志','悬疑案'].map(c=>`<button class="filter ${category===c?'active':''}" data-category="${c}" aria-pressed="${category===c}">${c}</button>`).join('')}</div><label class="search"><span aria-hidden="true">⌕</span><input id="story-search" type="search" aria-label="搜索故事或单词" placeholder="搜标题 / 线索 / 六级词" value="${esc(search)}"></label></div><div class="library-caption"><span id="story-count"></span><button data-action="sort" aria-pressed="${sortUnread}">⇅ ${sortUnread?'未读优先':'默认顺序'}</button></div><div id="story-grid" class="story-grid"></div></section><div class="reading-note"><b>☁</b><div><strong>建议顺序：中文 → 英文 → 词汇 → 回忆。</strong><br>每篇故事都将中文放在第一视觉层；英文原文默认收起，避免还没理解场景就被单词打断。</div></div>`;renderCards();}

function formatEnglish(text){return text.split(/(\[\[.*?\]\])/g).map(part=>{if(!part.startsWith('[['))return esc(part);const word=part.slice(2,-2),w=getWord(word.toLowerCase());return w?`<button class="word-inline ${state.words[w.id]?.stage>0?'known':''}" data-word="${esc(w.id)}" lang="en">${esc(word)}</button>`:esc(word);}).join('');}
function reader(id){const s=getStory(id);if(!s){main.innerHTML='<div class="empty-state"><h2>这篇故事不存在</h2><a class="button" href="#library">回到书架</a></div>';return;}state.lastStory=s.id;save();const english=state.preferences.english;main.innerHTML=`<div class="reader-top"><a href="#library" class="back-link">← 回到故事书架</a><div class="reader-controls"><button class="button secondary compact" data-action="toggle-english" aria-pressed="${english}">${english?'收起英文':'展开英文原文'}</button><button class="button secondary compact" data-action="read-aloud">▷ 朗读英文</button><button class="button secondary compact" data-action="focus">${document.body.classList.contains('focus-mode')?'退出专注':'专注阅读'}</button></div></div><div class="reader-layout"><article class="reader-paper"><div class="eyebrow">CHAPTER ${String(s.number).padStart(2,'0')} · ${esc(s.category)} · ${esc(s.tag)}</div><h1>${esc(s.title)}</h1><div class="reader-subtitle">${esc(s.en)}</div><div class="reader-meta">先中文语境 · ${s.words.length} 个重点词 · ${esc(s.mood)}<br><span class="practice-label">以下为原创 CET-6 风格仿真训练，非官方真题。</span></div>${s.cn.map((cn,i)=>`<section class="scene-block"><div class="scene-number">${String(i+1).padStart(2,'0')}</div><p class="reader-paragraph chinese-first" lang="zh-CN">${esc(cn)}</p><p class="translation english-second" lang="en" ${english?'':'hidden'}>${formatEnglish(s.en[i])}</p></section>`).join('')}<div class="reader-end"><div class="eyebrow">READ · RECALL · RETELL</div><p>合上英文后，试着用中文复述这一段发生了什么，再说出你记得的英文词。</p><div class="hero-actions"><button class="button" data-action="story-quiz" data-story="${s.id}">读完了，开始回忆 <span>→</span></button><button class="text-link" data-action="complete-story" data-story="${s.id}">${state.completed.includes(s.id)?'✓ 已标记读完':'标记读完'}</button></div></div></article><aside class="reader-aside"><h2>本章词签</h2><p>词汇从中文画面里出现。点击查看释义、搭配和复习状态。</p><div class="words">${s.words.map(w=>`<div class="word-row"><button data-word="${w.id}" lang="en">${esc(w.word)}<small>${esc(w.pos)} · ${esc(w.meaning)}</small></button><button class="mark" data-action="favorite" data-id="${w.id}" aria-label="收藏 ${esc(w.word)}">${state.favorites.includes(w.id)?'★':'☆'}</button></div>`).join('')}</div><div class="aside-box"><b>本章记忆进度</b><span>${s.words.filter(w=>state.words[w.id]?.stage>0).length} / ${s.words.length} 已掌握</span><div class="tiny-progress"><span style="width:${s.words.filter(w=>state.words[w.id]?.stage>0).length/s.words.length*100}%"></span></div></div></aside></div>`;}

function wordModal(id){const w=getWord(id);if(!w)return;selectedWord=id;const p=state.words[id];document.getElementById('word-content').innerHTML=`<div class="dialog-inner"><div class="dialog-top"><h2 id="word-title" class="english-title" lang="en">${esc(w.word)}</h2><button class="close-button" data-action="close-word" aria-label="关闭">×</button></div><p>${esc(w.pos)} <button class="text-link" data-action="speak-word">◖ 发音</button></p><div class="word-meaning">${esc(w.meaning)}</div><p class="word-context-label">中文语境优先</p>${w.phrase?`<p>常用搭配：<strong lang="en">${esc(w.phrase)}</strong></p>`:''}${w.example?`<div class="word-example" lang="en">${esc(w.example)}</div>`:''}<label class="note-label" for="word-note">我的联想 / 笔记</label><textarea id="word-note" placeholder="写一句自己的中文联想，帮助下次回忆">${esc(state.notes[id]||'')}</textarea><div class="word-source">来自「${esc(w.source)}」${p?` · 下次复习：${esc(p.due)}`:''}</div><div class="dialog-buttons"><button class="button compact" data-action="remember-word">✓ ${p?.stage>0?'再确认记住了':'我记住了'}</button><button class="button secondary compact" data-action="forget-word">还不熟，加入复习</button><button class="button secondary compact" data-action="save-note">保存笔记</button><button class="button secondary compact" data-action="favorite" data-id="${esc(w.id)}">${state.favorites.includes(id)?'★ 已收藏':'☆ 收藏'}</button></div></div>`;if(!wordDialog.open)wordDialog.showModal();}

function review(){const due=dueWords(),freshWords=allWords().filter(w=>!state.words[w.id]);main.innerHTML=`<div class="page-heading"><div class="eyebrow">ACTIVE RECALL · SPACED REVIEW</div><h1>先回想，再看答案。</h1><p>中文画面负责理解，英文拼写负责提取。今天已学习 ${state.activity[today()]?.length||0} / ${state.goal} 个词。</p></div>${stats()}<div class="review-layout"><section class="review-card"><div class="eyebrow">TODAY'S MISSION</div><h2>${due.length?`今天有 ${due.length} 个词回来找你。`:'今天暂时没有到期词。'}</h2><p>${due.length?'每轮最多练习 12 词：先根据中文释义和例句回忆英文，再检查答案。答错的词会重新回到当天队列。':`词库里还有 ${freshWords.length} 个未学习词。可以从新章节开始，也可以立即随机抽取练习。`}</p><div class="review-options"><button class="button" data-action="due-quiz" ${due.length?'':'disabled'}>开始到期复习 <span>→</span></button><button class="button secondary" data-action="free-quiz">随机练 12 词</button></div><a class="text-link" href="#library">去故事书架，先读一段中文语境 ↗</a></section><aside class="review-mini"><h3>记忆间隔</h3><p>每次主动回忆成功，间隔逐步拉长；不确定就诚实选“还不熟”。</p>${[[1,'第一次记住','1 天后'],[2,'第二次回忆','3 天后'],[3,'第三次回忆','7 天后'],[4,'持续巩固','14 天后']].map(x=>`<div class="schedule-step"><b>${x[0]}</b><span>${x[1]} · ${x[2]}</span></div>`).join('')}<p class="practice-label">进度保存在本机。换设备前请到词本导出备份。</p></aside></div>`;}

function startQuiz(words,storyId=null){if(!words.length){toast('当前没有可练习的词，先读一篇故事吧。');return;}quiz={words:shuffle(words).slice(0,12),storyId,index:0,correct:0,wrong:[],mode:'choice',answered:false,choice:'',options:[],finished:false};location.hash='quiz';}
function quizPage(){if(!quiz){main.innerHTML='<div class="empty-state"><h2>还没有开始练习</h2><a class="button" href="#review">去今日复习</a></div>';return;}if(quiz.finished){quizResult();return;}const w=quiz.words[quiz.index];if(!quiz.options.length)quiz.options=shuffle([w,...shuffle(allWords().filter(x=>x.id!==w.id)).slice(0,3)]);const sentence=(w.example||`The word ${w.word} appears in a meaningful context.`).replace(new RegExp(`\\b${w.word.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')}\\b`,'ig'),'________');main.innerHTML=`<div class="reader-top"><a href="#review" class="back-link">← 退出本轮练习</a><div class="mode-buttons"><button data-mode="choice" class="${quiz.mode==='choice'?'active':''}" ${quiz.answered?'disabled':''}>语境选择</button><button data-mode="spelling" class="${quiz.mode==='spelling'?'active':''}" ${quiz.answered?'disabled':''}>拼写回忆</button></div></div><div class="review-layout"><section class="review-card"><div class="quiz-top"><span>主动回忆 · ${quiz.mode==='choice'?'根据中文选英文':'看中文写英文'}</span><span>${quiz.index+1} / ${quiz.words.length}</span></div><div class="quiz-bar"><span style="width:${quiz.index/quiz.words.length*100}%"></span></div><div class="quiz-context">${esc(w.source)} · ${esc(w.pos)}</div><div class="quiz-cn">${esc(w.meaning)}</div><div class="quiz-sentence" lang="en">${esc(sentence)}</div>${quiz.mode==='choice'?`<div class="answer-grid">${quiz.options.map((o,i)=>`<button class="answer ${quiz.answered?(o.id===w.id?'correct':quiz.choice===o.id?'wrong':''):''}" data-answer="${esc(o.id)}" ${quiz.answered?'disabled':''}><b>${'ABCD'[i]}</b><span lang="en">${esc(o.word)}</span></button>`).join('')}</div>`:`<form id="spelling-form"><label class="quiz-context" for="spell-input">输入英文单词</label><input id="spell-input" class="spelling-input" autocomplete="off" autocapitalize="off" spellcheck="false" ${quiz.answered?'disabled':''} value="${quiz.answered?esc(quiz.choice):''}" placeholder="先想一想，再输入"><button class="button compact" type="submit" ${quiz.answered?'disabled':''}>检查答案</button></form>`}${quiz.answered?`<div class="answer-feedback ${quiz.choice===w.id?'good':'bad'}"><b>${quiz.choice===w.id?'回答正确':'再见一次'}</b><span>答案：<strong lang="en">${esc(w.word)}</strong> · ${esc(w.meaning)}</span></div><button class="button" data-action="next-question">${quiz.index+1===quiz.words.length?'查看结果':'下一题'} →</button>`:''}</section><aside class="review-mini"><h3>回到语境</h3><p>如果想不起，不要硬猜。打开词汇详情，看看它来自哪一篇修仙志或悬疑案。</p><button class="text-link" data-word="${esc(w.id)}">查看 ${esc(w.word)} ↗</button></aside></div>`;}
function answer(value){if(!quiz||quiz.answered)return;const w=quiz.words[quiz.index],normalized=value.trim().toLowerCase();if(!normalized){toast('先输入或选择答案。');return;}quiz.choice=normalized;quiz.answered=true;if(normalized===w.id)quiz.correct++;else quiz.wrong.push(w);record(w.id,normalized===w.id);quizPage();}
function quizResult(){main.innerHTML=`<div class="page-heading"><div class="eyebrow">ACTIVE RECALL COMPLETE</div><h1>这一轮，记忆有了回声。</h1></div><section class="review-card result-card"><div class="result-number">${quiz.correct}<small> / ${quiz.words.length}</small></div><h2>${quiz.correct===quiz.words.length?'全部想起来了。':'认识它们，也是一种进步。'}</h2><p>正确回忆已安排下一次复习。${quiz.storyId?'本章也已标记读完。':''}</p>${quiz.wrong.length?`<p>建议再见一次：</p><div class="result-list">${quiz.wrong.map(w=>`<button data-word="${w.id}">${esc(w.word)}</button>`).join('')}</div>`:'<div class="completion">✓ 本轮全部正确</div>'}<div class="hero-actions"><button class="button" data-action="retry-wrong" ${quiz.wrong.length?'':'hidden'}>再练错词 →</button><a class="button secondary" href="#review">回到复习</a><a class="text-link" href="#library">再读一篇故事 ↗</a></div></section>`;}

function notebook(){main.innerHTML=`<div class="page-heading"><div class="eyebrow">WORD BANK · ${allWords().length} WORDS</div><h1>我的词本，保存每一次想起。</h1><p>故事重点词与六级扩展词统一管理。可以收藏、写联想、朗读、复习和备份。</p></div><div class="notebook-top"><label class="search"><span>⌕</span><input id="notebook-search" type="search" placeholder="搜索英文 / 中文释义" value="${esc(notebookSearch)}"></label><div class="notebook-actions"><button class="button secondary compact" data-action="backup">导出进度</button><button class="button secondary compact" data-action="restore">恢复备份</button><button class="button compact" data-action="import-words">＋ 添加生词</button></div></div><div class="filters">${[['all','全部词汇'],['story','故事重点词'],['core','六级扩展词'],['favorite','我的收藏'],['due','到期复习'],['new','尚未学习'],['learned','已记住']].map(([id,t])=>`<button class="filter ${notebookFilter===id?'active':''}" data-notebook="${id}">${t}</button>`).join('')}</div><div id="word-list"></div><p class="practice-label">${storageAvailable?'进度自动保存在当前浏览器。':'当前浏览器无法保存进度，请及时导出备份。'}</p><input type="file" id="backup-input" accept=".json,application/json" hidden>`;renderWordList();}
function renderWordList(){const list=allWords().filter(w=>{const p=state.words[w.id],match=notebookFilter==='all'||notebookFilter==='story'&&w.storyId||notebookFilter==='core'&&!w.storyId&&w.source==='六级核心词库'||notebookFilter==='favorite'&&state.favorites.includes(w.id)||notebookFilter==='due'&&p?.due<=today()||notebookFilter==='new'&&!p||notebookFilter==='learned'&&p?.stage>0;return match&&(!notebookSearch||`${w.word} ${w.meaning} ${w.source}`.toLowerCase().includes(notebookSearch.toLowerCase()));});const el=document.getElementById('word-list');if(!el)return;el.innerHTML=list.length?`<div class="library-caption"><span>找到 ${list.length} 个词</span><span>共 ${allWords().length} 个可学习词</span></div><div class="word-table-wrap"><table class="word-table"><thead><tr><th>单词 / WORD</th><th>中文释义</th><th>来源</th><th>状态</th><th>操作</th></tr></thead><tbody>${list.slice(0,notebookLimit).map(w=>{const [cl,status]=statusFor(w);return `<tr><td><button class="table-word" data-word="${w.id}" lang="en">${esc(w.word)}</button><div class="practice-label">${esc(w.pos)}</div></td><td>${esc(w.meaning)}</td><td>${w.storyId?`<a href="#story/${w.storyId}">${esc(w.source)} ↗</a>`:esc(w.source)}</td><td><span class="word-status ${cl}">${status}</span>${state.words[w.id]?`<div class="practice-label">${state.words[w.id].due}</div>`:''}</td><td><div class="table-actions"><button class="icon-button" data-action="speak" data-id="${w.id}" aria-label="朗读">◖</button><button class="icon-button" data-action="favorite" data-id="${w.id}" aria-label="收藏">${state.favorites.includes(w.id)?'★':'☆'}</button></div></td></tr>`;}).join('')}</tbody></table></div>${list.length>notebookLimit?'<button class="button secondary load-more" data-action="more-words">再显示 40 个词</button>':''}`:`<div class="empty-state"><h2>这里暂时没有词</h2><p>去读一篇故事，或添加自己的生词。</p></div>`;}
function utility(title,body){document.getElementById('utility-content').innerHTML=`<div class="dialog-inner"><div class="dialog-top"><h2 id="utility-title">${title}</h2><button class="close-button" data-action="close-utility">×</button></div>${body}</div>`;if(!utilityDialog.open)utilityDialog.showModal();}
function speak(text){if(!('speechSynthesis' in window)){toast('当前浏览器不支持朗读。');return;}if(activeSpeech===text&&speechSynthesis.speaking){speechSynthesis.cancel();activeSpeech=null;return;}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='en-GB';u.rate=.84;activeSpeech=text;u.onend=()=>activeSpeech=null;speechSynthesis.speak(u);toast(text.length>80?'正在朗读，再点一次可停止。':`正在朗读 ${text}`);}
function exportBackup(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`wordscene-progress-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('已导出学习进度');}
function addWords(){const raw=document.getElementById('import-text').value.trim(),lines=raw?raw.split('\n'):[],existing=new Set(allWords().map(w=>w.id)),newWords=[],bad=[];lines.forEach((line,i)=>{const [word,meaning,...example]=line.split('|').map(x=>x.trim());if(!/^[a-z][a-z '-]{0,49}$/i.test(word||'')||!meaning)bad.push(i+1);else if(!existing.has(word.toLowerCase())){newWords.push({id:word.toLowerCase(),word:word.toLowerCase(),meaning,pos:'自定义',phrase:'',example:example.join(' | '),source:'我的生词',storyId:null});existing.add(word.toLowerCase());}});if(bad.length){document.getElementById('import-error').textContent=`第 ${bad.join('、')} 行格式有误，请使用：英文 | 中文释义 | 英文例句（可选）。`;return;}state.custom.push(...newWords);save();utilityDialog.close();notebookFilter='all';notebook();toast(newWords.length?`已添加 ${newWords.length} 个生词`:'这些词已经在词本里了');}
function render(){if(!main)return;if('speechSynthesis'in window)speechSynthesis.cancel();if(wordDialog&&wordDialog.close)wordDialog.close();if(utilityDialog&&utilityDialog.close)utilityDialog.close();const [route,id]=location.hash.slice(1).split('/');if(route!=='story')document.body.classList.remove('focus-mode');if(route==='story')reader(id);else if(route==='review')review();else if(route==='notebook')notebook();else if(route==='quiz')quizPage();else library();updateNav();}

document.addEventListener('click',e=>{const el=e.target.closest('button,a,[data-word]');if(!el)return;if(el.dataset.word){wordModal(el.dataset.word);return;}if(el.dataset.category){category=el.dataset.category;document.querySelectorAll('[data-category]').forEach(b=>b.classList.toggle('active',b.dataset.category===category));renderCards();return;}if(el.dataset.notebook){notebookFilter=el.dataset.notebook;notebookLimit=40;document.querySelectorAll('[data-notebook]').forEach(b=>b.classList.toggle('active',b.dataset.notebook===notebookFilter));renderWordList();return;}if(el.dataset.mode&&quiz&&!quiz.answered){quiz.mode=el.dataset.mode;quizPage();return;}if(el.dataset.answer){answer(el.dataset.answer);return;}const action=el.dataset.action,id=el.dataset.id;
  if(action==='sort'){sortUnread=!sortUnread;el.innerHTML=`⇅ ${sortUnread?'未读优先':'默认顺序'}`;renderCards();}
  else if(action==='clear-search'){search='';category='全部';library();}
  else if(action==='toggle-english'){state.preferences.english=!state.preferences.english;save();reader(location.hash.split('/')[1]);}
  else if(action==='focus'){document.body.classList.toggle('focus-mode');reader(location.hash.split('/')[1]);}
  else if(action==='favorite'){const on=state.favorites.includes(id);state.favorites=on?state.favorites.filter(x=>x!==id):[...state.favorites,id];save();if(location.hash==='#notebook')renderWordList();else if(location.hash.startsWith('#story/'))reader(location.hash.split('/')[1]);toast(on?'已取消收藏':'已收藏到我的词本');}
  else if(action==='close-word')wordDialog.close();else if(action==='close-utility')utilityDialog.close();
  else if(action==='remember-word'||action==='forget-word'){record(selectedWord,action==='remember-word');wordDialog.close();render();toast(action==='remember-word'?'已安排下一次复习。':'已加入今天的复习队列。');}
  else if(action==='save-note'){state.notes[selectedWord]=document.getElementById('word-note').value.slice(0,500);save();wordDialog.close();toast('联想笔记已保存');}
  else if(action==='speak-word')speak(getWord(selectedWord).word);else if(action==='speak')speak(getWord(id).word);
  else if(action==='read-aloud'){const s=getStory(location.hash.split('/')[1]);if(s)speak(s.en.join(' ').replace(/\[\[(.*?)\]\]/g,'$1'));}
  else if(action==='complete-story'){const sid=el.dataset.story;if(!state.completed.includes(sid))state.completed.push(sid);save();el.textContent='✓ 已标记读完';toast('本章已标记读完。');}
  else if(action==='story-quiz'){const s=getStory(el.dataset.story);startQuiz(s.words,s.id);}
  else if(action==='due-quiz')startQuiz(dueWords());else if(action==='free-quiz')startQuiz(allWords());
  else if(action==='next-question'&&quiz?.answered){if(quiz.index+1===quiz.words.length){quiz.finished=true;if(quiz.storyId&&!state.completed.includes(quiz.storyId)){state.completed.push(quiz.storyId);save();}}else{quiz.index++;quiz.answered=false;quiz.choice='';quiz.options=[];}quizPage();}
  else if(action==='retry-wrong'&&quiz)startQuiz(quiz.wrong);
  else if(action==='backup')exportBackup();else if(action==='restore')document.getElementById('backup-input').click();else if(action==='more-words'){notebookLimit+=40;renderWordList();}
  else if(action==='import-words')utility('添加自己的生词','<p>每行一个词。建议把它放进你自己的中文画面里。</p><label for="import-text">英文单词 | 中文释义 | 英文例句（可选）</label><textarea id="import-text" placeholder="wander | 漫步；徘徊 | We wander through the fog."></textarea><div id="import-error" class="error-message"></div><div class="dialog-buttons"><button class="button" data-action="save-import">添加到词本 →</button></div><p>已有词会自动跳过。</p>');
  else if(action==='save-import')addWords();
  else if(action==='save-goal'){state.goal=Number(document.getElementById('goal-select').value);save();utilityDialog.close();render();toast('每日目标已更新');}
});
document.addEventListener('input',e=>{if(e.target.id==='story-search'){search=e.target.value;renderCards();}else if(e.target.id==='notebook-search'){notebookSearch=e.target.value;notebookLimit=40;renderWordList();}});
document.addEventListener('submit',e=>{if(e.target.id==='spelling-form'){e.preventDefault();answer(document.getElementById('spell-input').value);}});
document.addEventListener('change',async e=>{if(e.target.id!=='backup-input')return;const file=e.target.files[0];if(!file)return;try{const raw=JSON.parse(await file.text());if(!raw||!raw.words)throw Error('不是有效的词间备份');const incoming=cleanState(raw);state.custom=[...new Map([...state.custom,...incoming.custom].map(w=>[w.id,w])).values()].slice(0,1500);state.words={...state.words,...incoming.words};state.favorites=[...new Set([...state.favorites,...incoming.favorites])];state.completed=[...new Set([...state.completed,...incoming.completed])];state.notes={...state.notes,...incoming.notes};for(const [d,ids] of Object.entries(incoming.activity))state.activity[d]=[...new Set([...(state.activity[d]||[]),...ids])];state=cleanState(state);save();notebook();toast('备份已合并');}catch(err){toast(`恢复失败：${err.message}`);}finally{e.target.value='';}});
const goalButton=document.getElementById('goal-button');
if(goalButton)goalButton.addEventListener('click',()=>utility('设置今日目标',`<p>目标按今天学习过的不同单词计算。中文阅读、词汇确认和练习都会记录进度。</p><label for="goal-select">每日词汇目标</label><select id="goal-select">${[10,20,30,50].map(n=>`<option value="${n}" ${state.goal===n?'selected':''}>每天 ${n} 个词</option>`).join('')}</select><div class="dialog-buttons"><button class="button" data-action="save-goal">保存目标</button></div>`));
const aboutButton=document.getElementById('about-button');
if(aboutButton)aboutButton.addEventListener('click',()=>utility('词间 · 中文语境优先',`<p>这里不是把六级词汇塞进爽文，而是先让你看懂一段完整的中文情境，再逐步展开英文、词义和主动回忆。</p><p>当前内置 ${STORIES.length} 篇原创故事、${STORY_WORDS.length} 个故事重点词，以及 ${EXTRA_WORDS.length} 个六级扩展词。词库采用可导入结构，可继续加入你的完整六级词表。</p><p>所有学习进度、收藏、联想笔记都保存在当前浏览器；可在「我的词本」导出备份。朗读使用设备英语语音。</p>`));
for(const dialog of [wordDialog,utilityDialog])if(dialog)dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close();});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);if(main&&main.focus)main.focus({preventScroll:true});});
// learning.js restores the complete state before the initial render.
